using AOI.Runtime.Plc;
using Microsoft.Data.Sqlite;
using NUnit.Framework;
using System.Security.Cryptography;
using System.Text.Json;

namespace AOI.Tests;

/// <summary>
/// Agent05 independent native C# byte-level check of A1 ClaimId + A2 actual
/// FINS UDP + A7 SHA/SID, against real five-process evidence generated by A0.
/// No PLC sockets or production code changes. Python companion separately
/// mutates isolated on-disk copies and checks the full three-ledger lineage.
/// </summary>
[TestFixture]
[NonParallelizable]
public sealed class Agent05ClaimWireTamperTests
{
    private sealed record StepEvidence(Guid WorkpieceId, Guid ClaimId, Guid OperationId,
        byte Sid, ushort Address, ushort Value, string RequestSha, string? ReplySha,
        byte[] Request, byte[] Reply, bool AckExpected);

    private static SqliteConnection OpenReadOnly(string path)
    {
        if (!File.Exists(path))
            throw new InvalidDataException("Missing real five-process WAL: " + path);
        var connection = new SqliteConnection(new SqliteConnectionStringBuilder
        {
            DataSource = path, Mode = SqliteOpenMode.ReadOnly, Pooling = false
        }.ToString());
        connection.Open();
        return connection;
    }

    private static string Scalar(SqliteConnection db, string sql, string arg, object value)
    {
        using var command = db.CreateCommand();
        command.CommandText = sql;
        command.Parameters.AddWithValue(arg, value);
        return (string)(command.ExecuteScalar()
            ?? throw new InvalidDataException("Missing actual persisted record: " + sql));
    }

    private static string Root(string scenario)
    {
        string? value = Environment.GetEnvironmentVariable("AOI_A5_TAMPER_EVIDENCE_ROOT");
        if (string.IsNullOrWhiteSpace(value))
        {
            Assert.Ignore("NOT_VERIFIED: real five-process evidence root not supplied; " +
                "run dedicated A5 Windows/Linux evidence workflow.");
            throw new InvalidOperationException("Evidence root required");
        }
        string path = Path.Combine(Path.GetFullPath(value), scenario);
        if (!Directory.Exists(path))
            throw new InvalidDataException("NOT_VERIFIED: missing real " + scenario + " five-process run");
        return path;
    }

    private static JsonElement[] Wire(string path)
    {
        string file = Path.Combine(path, "p0-fins-wire.jsonl");
        if (!File.Exists(file)) throw new InvalidDataException("Missing original FINS UDP wire recorder");
        return File.ReadLines(file).Where(line => !string.IsNullOrWhiteSpace(line))
            .Select(line => JsonDocument.Parse(line).RootElement.Clone()).ToArray();
    }

    private static string Digest(ReadOnlySpan<byte> bytes) =>
        Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();

    private static void CheckOriginalPacket(StepEvidence proof)
    {
        if (proof.ClaimId == Guid.Empty || proof.ClaimId != proof.OperationId)
            throw new InvalidDataException("A1 ClaimId does not equal A7/A2 OperationId");
        if (!LegacyFinsWire.TryParseRequest(proof.Request, LegacyFinsNodes.Demo, out var write)
            || !write.IsWrite || write.Sid != proof.Sid || write.Address != proof.Address ||
            write.Values.Length != 1 || write.Values[0] != proof.Value)
            throw new InvalidDataException("Actual FINS UDP write/SID/value not proven");
        if (!string.Equals(Digest(proof.Request), proof.RequestSha, StringComparison.OrdinalIgnoreCase))
            throw new InvalidDataException("Original network request SHA256 differs from A7 journal");
        if (proof.AckExpected)
        {
            if (proof.Reply.Length == 0 || string.IsNullOrEmpty(proof.ReplySha) ||
                !string.Equals(Digest(proof.Reply), proof.ReplySha, StringComparison.OrdinalIgnoreCase))
                throw new InvalidDataException("False ACK: A7 reply hash not backed by received UDP bytes");
            try
            {
                ushort[] response = LegacyFinsWire.DecodeResponse(
                    proof.Request, proof.Reply, LegacyFinsNodes.Demo);
                if (response.Length != 0)
                    throw new InvalidDataException("FINS write ACK cannot contain readback words");
            }
            catch (Exception exception) when (exception is ArgumentException or InvalidDataException)
            {
                throw new InvalidDataException("Actual FINS response SID/route/end-code refused", exception);
            }
        }
        else if (proof.Reply.Length != 0 || !string.IsNullOrEmpty(proof.ReplySha))
            throw new InvalidDataException("Unknown ACK must not have a synthetic reply");
    }

    private static StepEvidence LoadActualStep(string scenario, int token, ushort address, ushort expected, int stepNumber)
    {
        string root = Root(scenario);
        using var core = OpenReadOnly(Path.Combine(root, "master", "sim-full-cycle.db"));
        string identity = Scalar(core,
            "SELECT identity_json FROM sim_full_tokens WHERE token=$token", "$token", token);
        using var id = JsonDocument.Parse(identity);
        Guid workpiece = Guid.Parse(id.RootElement.GetProperty("workpieceId").GetString()!);
        using var a1 = OpenReadOnly(Path.Combine(root, "master", "final-plc-output.db"));
        using var claims = a1.CreateCommand();
        claims.CommandText = "SELECT event_json FROM a1_final_output_events WHERE workpiece_id=$item ORDER BY sequence";
        claims.Parameters.AddWithValue("$item", workpiece.ToString("D"));
        var foundClaims = new List<Guid>();
        using (var reader = claims.ExecuteReader())
        {
            while (reader.Read())
            {
                using var payload = JsonDocument.Parse(reader.GetString(0));
                JsonElement data = payload.RootElement;
                if (data.GetProperty("kind").GetString() == "writeClaimed")
                    foundClaims.Add(Guid.Parse(data.GetProperty("claimId").GetString()!));
            }
        }
        if (foundClaims.Count is < 1 or > 2 || foundClaims.Count < stepNumber)
            throw new InvalidDataException("Wrong number of A1 one-time write claims");
        Guid claim = foundClaims[stepNumber - 1];
        using var a7 = OpenReadOnly(Path.Combine(root, "master", "timing-events.sqlite"));
        string attempt = Scalar(a7,
            "SELECT attempt_id FROM final_output_intents WHERE token=$token",
            "$token", token); // also verify the workpiece identity below
        using var itemCheck = a7.CreateCommand();
        itemCheck.CommandText = "SELECT workpiece_id FROM final_output_intents WHERE attempt_id=$id";
        itemCheck.Parameters.AddWithValue("$id", attempt);
        if ((string?)itemCheck.ExecuteScalar() != workpiece.ToString("D"))
            throw new InvalidDataException("A7 WorkpieceId was swapped with a different Core item");
        using var step = a7.CreateCommand();
        step.CommandText = """
            SELECT phase,operation_id,fins_sid,dm_address,value,request_sha256,response_sha256
            FROM final_output_audit_events WHERE attempt_id=$attempt AND step_number=$step
            ORDER BY sequence
            """;
        step.Parameters.AddWithValue("$attempt", attempt);
        step.Parameters.AddWithValue("$step", stepNumber);
        var phases = new List<(string Phase, string? Operation, int? Sid, int? Address,
            int? Value, string? RequestSha, string? ReplySha)>();
        using (var reader = step.ExecuteReader())
            while (reader.Read())
                phases.Add((reader.GetString(0), reader.IsDBNull(1) ? null : reader.GetString(1),
                    reader.IsDBNull(2) ? null : reader.GetInt32(2),
                    reader.IsDBNull(3) ? null : reader.GetInt32(3),
                    reader.IsDBNull(4) ? null : reader.GetInt32(4),
                    reader.IsDBNull(5) ? null : reader.GetString(5),
                    reader.IsDBNull(6) ? null : reader.GetString(6)));
        bool lost = token == 3 && ((scenario == "ack-lost" && stepNumber == 1) ||
            (scenario == "ack-second" && stepNumber == 2));
        string[] expectedPhases = lost
            ? ["StepPrepared", "WireSent", "AckUnknown"]
            : ["StepPrepared", "WireSent", "AckAccepted", "ReadbackVerified"];
        if (!phases.Select(x => x.Phase).SequenceEqual(expectedPhases))
            throw new InvalidDataException("A7 step 1 Acknowledge phase sequence was modified");
        var prepared = phases[0];
        if (prepared.Address != address || prepared.Value != expected ||
            prepared.Sid is null || prepared.Sid < 0 || prepared.Sid > 255 || string.IsNullOrWhiteSpace(prepared.RequestSha))
            throw new InvalidDataException("A7 prepared physical DM/SID value was changed");
        Guid operation = Guid.Parse(prepared.Operation!);
        if (phases[1].Operation != prepared.Operation ||
            (!lost && phases[2].Operation != prepared.Operation))
            throw new InvalidDataException("A7 original ClaimId altered across phases");
        var matches = Wire(root).Where(e => e.GetProperty("Token").GetInt32() == token &&
            e.GetProperty("Address").GetInt32() == address &&
            e.GetProperty("IsWrite").GetBoolean()).ToArray();
        if (matches.Length != 1)
            throw new InvalidDataException("Extra, missing, or replayed FINS write for one claim");
        JsonElement packet = matches[0];
        byte[] request = Convert.FromHexString(packet.GetProperty("RequestHex").GetString()!);
        byte[] reply = Convert.FromHexString(packet.GetProperty("ResponseHex").GetString()!);
        if (packet.GetProperty("Sid").GetInt32() != prepared.Sid)
            throw new InvalidDataException("A2 reported SID differs from A7");
        return new StepEvidence(workpiece, claim, operation, (byte)prepared.Sid, address,
            expected, prepared.RequestSha!, lost ? null : phases[2].ReplySha,
            request, reply, !lost);
    }

    [TestCase("normal", 1, (ushort)1016, (ushort)2, 1)]
    [TestCase("mismatch", 3, (ushort)2099, (ushort)4, 1)]
    [TestCase("ack-lost", 3, (ushort)2099, (ushort)4, 1)]
    [TestCase("ack-second", 3, (ushort)1016, (ushort)2, 2)]
    [TestCase("scan-failed", 3, (ushort)2099, (ushort)3, 1)]
    public void ActualFiveProcessOriginalClaimAndFinsPacket_RejectsEachIndependentTamper(
        string scenario, int token, ushort address, ushort value, int stepNumber)
    {
        StepEvidence original = LoadActualStep(scenario, token, address, value, stepNumber);
        Assert.DoesNotThrow(() => CheckOriginalPacket(original),
            "Only original A1/A2/A7 same-run physical evidence is accepted");
        byte[] changedRequest = (byte[])original.Request.Clone();
        changedRequest[^1] ^= 1;
        Assert.Throws<InvalidDataException>(() => CheckOriginalPacket(original with
        {
            Request = changedRequest
        }), "Changing just one actual network request byte cannot leave an accepted Claim");
        Assert.Throws<InvalidDataException>(() => CheckOriginalPacket(original with
        {
            Sid = (byte)(original.Sid + 1)
        }), "A7 or metadata SID replacement must not authenticate the original FINS packet");
        Assert.Throws<InvalidDataException>(() => CheckOriginalPacket(original with
        {
            ClaimId = Guid.NewGuid()
        }), "Changing the A1 one-time ClaimId cannot masquerade as A2 OperationId");
        if (original.AckExpected)
        {
            byte[] changedReply = (byte[])original.Reply.Clone();
            changedReply[9] ^= 1; // Actual FINS returned SID, not JSON metadata.
            Assert.Throws<InvalidDataException>(() => CheckOriginalPacket(original with
            {
                Reply = changedReply
            }), "A received response whose SID differs must never confirm an output");
            Assert.Throws<InvalidDataException>(() => CheckOriginalPacket(original with
            {
                Reply = [], ReplySha = null
            }), "A lost reply cannot be promoted to successful ACK");
        }
        else
        {
            // For a lost-ACK case there is NO response packet. A bogus A7
            // response SHA cannot authorize the second physical write.
            Assert.Throws<InvalidDataException>(() => CheckOriginalPacket(original with
            {
                ReplySha = new string('0', 64)
            }));
        }
        TestContext.Progress.WriteLine($"A5_CSHARP_RAW_CLAIM_TAMPER_REJECTED " +
            $"scenario={scenario} token={token} sid={original.Sid} claim={original.ClaimId} " +
            "original_A1_A2_A7_PASS=1 mutated_request_sid_claim_ack_REJECTED=1");
    }
}
